'use client';

import { useMemo, useRef } from 'react';
import * as THREE from 'three';

interface SubstrateProps {
  tankBounds: THREE.Vector3;
  pebbleCount?: number;
}

export default function Substrate({ tankBounds, pebbleCount = 80 }: SubstrateProps) {
  const pebblesRef = useRef<THREE.InstancedMesh>(null);

  // 1. Engebeli Kum Geometrisi Hesabı
  const sandGeometry = useMemo(() => {
    const geom = new THREE.PlaneGeometry(tankBounds.x, tankBounds.z, 32, 32);
    geom.rotateX(-Math.PI / 2);

    const pos = geom.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const x = pos.getX(i);
      const z = pos.getZ(i);
      const y = Math.sin(x * 1.5) * Math.cos(z * 1.5) * 0.08;
      pos.setY(i, y);
    }
    geom.computeVertexNormals();
    return geom;
  }, [tankBounds]);

  // 2. Çakıl Taşları Matris Hesabı (InstancedMesh)
  const pebbleData = useMemo(() => {
    const geom = new THREE.DodecahedronGeometry(0.22, 1);
    const mat = new THREE.MeshStandardMaterial({
      color: 0x5a5d61,
      roughness: 0.7,
    });

    const matrices: THREE.Matrix4[] = [];
    const dummy = new THREE.Object3D();
    const bottomY = -tankBounds.y / 2 + 0.1;

    for (let i = 0; i < pebbleCount; i++) {
      dummy.position.set(
        (Math.random() - 0.5) * (tankBounds.x - 1.2),
        bottomY,
        (Math.random() - 0.5) * (tankBounds.z - 1.2)
      );
      dummy.rotation.set(Math.random(), Math.random(), Math.random());
      dummy.scale.set(
        0.5 + Math.random() * 0.7,
        0.25 + Math.random() * 0.3,
        0.5 + Math.random() * 0.7
      );
      dummy.updateMatrix();
      matrices.push(dummy.matrix.clone());
    }

    return { geom, mat, matrices };
  }, [tankBounds, pebbleCount]);

  return (
    <group>
      {/* 1. Kum Zemin Mesh'i */}
      <mesh
        geometry={sandGeometry}
        position={[0, -tankBounds.y / 2, 0]}
      >
        <meshStandardMaterial color="#cfb285" roughness={0.95} />
      </mesh>

      {/* 2. Çakıl Taşları InstancedMesh'i */}
      <instancedMesh
        ref={pebblesRef}
        args={[pebbleData.geom, pebbleData.mat, pebbleCount]}
        onUpdate={(self) => {
          pebbleData.matrices.forEach((mat, i) => {
            self.setMatrixAt(i, mat);
          });
          self.instanceMatrix.needsUpdate = true;
        }}
      />
    </group>
  );
}