import * as THREE from 'three';
import { GLTFLoader } from 'three/examples/jsm/loaders/GLTFLoader.js';
import { DRACOLoader } from 'three/examples/jsm/loaders/DRACOLoader.js';
import * as SkeletonUtils from 'three/examples/jsm/utils/SkeletonUtils.js';

export interface FishPhysicsConfig {
  minSpeed: number;
  maxSpeed: number;
  diveInterval: number;
  verticalFreedom: number;
  turnSpeed: number;
}

export interface SwimShaderConfig {
  bodySpeed?: number;
  bodyFreq?: number;
  bodyAmp?: number;
  finSpeed?: number;
  pectoralAmp?: number;
  caudalWhip?: number;
}

export interface FishAppearanceConfig {
  color?: string;
  roughness?: number;
  metalness?: number;
}

export interface FishConfig {
  id: string;
  name: string;
  modelPath: string;
  texturePath?: string;
  appearance?: FishAppearanceConfig;
  behavior?: 'normal' | 'bottom_dweller';
  physics: FishPhysicsConfig;
  swimShader: SwimShaderConfig;
}

interface FishInstance {
  model: THREE.Object3D;
  velocity: THREE.Vector3;
  targetVelocity: THREE.Vector3;
  speed: number;
  config: FishConfig;
  preferredDepth: number;
  timer: number;
  tail?: THREE.Object3D;
  finLBig?: THREE.Object3D;
  finLSmall?: THREE.Object3D;
  finRBig?: THREE.Object3D;
  finRSmall?: THREE.Object3D;
  finDorsal?: THREE.Object3D;
}

interface LoadedTemplate {
  model: THREE.Object3D;
  config: FishConfig;
}

export class FishManager {
  private scene: THREE.Scene;
  private bounds: THREE.Vector3;
  private targetCount: number;
  private configs: FishConfig[];
  private templates: LoadedTemplate[] = [];
  private fishList: FishInstance[] = [];
  private loader!: GLTFLoader;
  private textureLoader: THREE.TextureLoader;
  
  private eyeIrisMaterial: THREE.MeshBasicMaterial;
  private pupilMaterial: THREE.MeshBasicMaterial;

  constructor(scene: THREE.Scene, tankBounds: THREE.Vector3, count = 20, configs: FishConfig[] = []) {
    this.scene = scene;
    this.bounds = tankBounds;
    this.targetCount = count;
    this.configs = configs;

    this.textureLoader = new THREE.TextureLoader();
    this.eyeIrisMaterial = new THREE.MeshBasicMaterial({ color: 0x734d14 });
    this.pupilMaterial = new THREE.MeshBasicMaterial({ color: 0x010101 });

    this.initLoader();
    if (this.configs.length > 0) {
      this.loadModels();
    }
  }

  private initLoader() {
    const dracoLoader = new DRACOLoader();
    dracoLoader.setDecoderPath('https://www.gstatic.com/draco/versioned/decoders/1.5.6/');

    this.loader = new GLTFLoader();
    this.loader.setDRACOLoader(dracoLoader);
  }

  public loadModels() {
    this.clearAllFish();

    const promises = this.configs.map((cfg) => {
      return new Promise<LoadedTemplate | null>((resolve) => {
        // Doku tamamen config içindeki texturePath değerinden yüklenir
        let fishMaterial: THREE.Material;

        if (cfg.texturePath) {
          const texture = this.textureLoader.load(cfg.texturePath, (tex) => {
            tex.colorSpace = THREE.SRGBColorSpace;
            tex.wrapS = THREE.RepeatWrapping;
            tex.wrapT = THREE.RepeatWrapping;
            tex.needsUpdate = true;
          });
          fishMaterial = new THREE.MeshBasicMaterial({
            map: texture,
            side: THREE.DoubleSide
          });
        } else {
          const colorHex = cfg.appearance?.color || '#8c928d';
          fishMaterial = new THREE.MeshBasicMaterial({
            color: new THREE.Color(colorHex),
            side: THREE.DoubleSide
          });
        }

        this.loader.load(
          cfg.modelPath,
          (gltf) => {
            const model = gltf.scene;

            model.traverse((child) => {
              if ((child as THREE.Mesh).isMesh) {
                const mesh = child as THREE.Mesh;
                const geometry = mesh.geometry;
                const lowerName = mesh.name.toLowerCase();

                // Modelde UV yoksa otomatik silindirik UV eklenir ki texture düzgün oturabilsin
                if (!geometry.attributes.uv) {
                  const pos = geometry.attributes.position;
                  const uvs = [];
                  for (let i = 0; i < pos.count; i++) {
                    const x = pos.getX(i);
                    const z = pos.getZ(i);
                    const u = (Math.atan2(z, x) / Math.PI + 1) * 0.5;
                    const v = (pos.getY(i) + 1) * 0.5;
                    uvs.push(u, v);
                  }
                  geometry.setAttribute('uv', new THREE.Float32BufferAttribute(uvs, 2));
                }

                if (lowerName.includes('pupil')) {
                  mesh.material = this.pupilMaterial;
                } else if (lowerName.includes('eye')) {
                  mesh.material = this.eyeIrisMaterial;
                } else {
                  mesh.material = fishMaterial;
                }
              }
            });

            resolve({ model, config: cfg });
          },
          undefined,
          (err) => {
            console.error(`[FishEngine] Model yüklenemedi: ${cfg.modelPath}`, err);
            resolve(null);
          }
        );
      });
    });

    Promise.all(promises).then((results) => {
      this.templates = results.filter((r): r is LoadedTemplate => r !== null);
      if (this.templates.length > 0) {
        this.setFishCount(this.targetCount);
      }
    });
  }

  public addFish() {
    if (this.templates.length === 0) return;

    const templateObj = this.templates[Math.floor(Math.random() * this.templates.length)];
    const { model, config } = templateObj;

    const margin = 0.8;
    const maxX = this.bounds.x / 2 - margin;
    const maxY = this.bounds.y / 2 - margin;
    const maxZ = this.bounds.z / 2 - margin;
    const bottomY = -this.bounds.y / 2 + 0.35;

    const fishClone = SkeletonUtils.clone(model);

    let tail: THREE.Object3D | undefined;
    let finLBig: THREE.Object3D | undefined;
    let finLSmall: THREE.Object3D | undefined;
    let finRBig: THREE.Object3D | undefined;
    let finRSmall: THREE.Object3D | undefined;
    let finDorsal: THREE.Object3D | undefined;

    fishClone.traverse((child) => {
      const n = child.name.toLowerCase();
      if (n.includes('tail')) tail = child;
      if (n.includes('fin_l_big') || (n.includes('fin') && n.includes('l') && n.includes('big'))) finLBig = child;
      if (n.includes('fin_l_small') || (n.includes('fin') && n.includes('l') && n.includes('small'))) finLSmall = child;
      if (n.includes('fin_r_big') || (n.includes('fin') && n.includes('r') && n.includes('big'))) finRBig = child;
      if (n.includes('fin_r_small') || (n.includes('fin') && n.includes('r') && n.includes('small'))) finRSmall = child;
      if (n.includes('dorsal')) finDorsal = child;
    });

    const isBottomDweller = config.behavior === 'bottom_dweller';
    const initialY = isBottomDweller ? bottomY : THREE.MathUtils.randFloat(-maxY * 0.4, maxY * 0.4);

    fishClone.position.set(
      THREE.MathUtils.randFloat(-maxX + 0.5, maxX - 0.5),
      initialY,
      THREE.MathUtils.randFloat(-maxZ + 0.5, maxZ - 0.5)
    );

    const speed = THREE.MathUtils.randFloat(config.physics.minSpeed, config.physics.maxSpeed);
    const velocity = new THREE.Vector3(
      THREE.MathUtils.randFloatSpread(1),
      isBottomDweller ? 0 : THREE.MathUtils.randFloatSpread(0.02),
      THREE.MathUtils.randFloatSpread(1)
    ).normalize().multiplyScalar(speed);

    this.scene.add(fishClone);

    this.fishList.push({
      model: fishClone,
      velocity: velocity,
      targetVelocity: velocity.clone(),
      speed: speed,
      config: config,
      preferredDepth: initialY,
      timer: Math.random() * config.physics.diveInterval,
      tail,
      finLBig,
      finLSmall,
      finRBig,
      finRSmall,
      finDorsal
    });
  }

  public removeFish() {
    if (this.fishList.length === 0) return;
    const fish = this.fishList.pop();
    if (fish) {
      this.scene.remove(fish.model);
    }
  }

  public setFishCount(newCount: number) {
    this.targetCount = newCount;
    if (this.templates.length === 0) return;

    while (this.fishList.length < newCount) this.addFish();
    while (this.fishList.length > newCount) this.removeFish();
  }

  public clearAllFish() {
    while (this.fishList.length > 0) {
      this.removeFish();
    }
  }

  public updateConfigs(newConfigs: FishConfig[]) {
    this.configs = newConfigs;
    this.loadModels();
  }

  public updateBounds(newBounds: THREE.Vector3) {
    this.bounds = newBounds;
  }

  public update(elapsedTime: number) {
    const margin = 0.6;
    const minX = -this.bounds.x / 2 + margin;
    const maxX = this.bounds.x / 2 - margin;
    const minY = -this.bounds.y / 2 + margin;
    const maxY = this.bounds.y / 2 - margin;
    const minZ = -this.bounds.z / 2 + margin;
    const maxZ = this.bounds.z / 2 - margin;
    const bottomY = -this.bounds.y / 2 + 0.35;

    for (let i = 0; i < this.fishList.length; i++) {
      const fish = this.fishList[i];

      const cycle = elapsedTime * 8.0 + (i * 1.2);
      
      if (fish.tail) {
        fish.tail.rotation.y = Math.sin(cycle) * 0.4;
      }
      if (fish.finLBig) {
        fish.finLBig.rotation.z = Math.cos(cycle) * 0.3;
      }
      if (fish.finLSmall) {
        fish.finLSmall.rotation.z = Math.cos(cycle + 0.5) * 0.2;
      }
      if (fish.finRBig) {
        fish.finRBig.rotation.z = -Math.cos(cycle) * 0.3;
      }
      if (fish.finRSmall) {
        fish.finRSmall.rotation.z = -Math.cos(cycle + 0.5) * 0.2;
      }
      if (fish.finDorsal) {
        fish.finDorsal.rotation.z = Math.sin(cycle * 0.7) * 0.15;
      }

      const pos = fish.model.position;
      const phys = fish.config.physics;
      const isBottomDweller = fish.config.behavior === 'bottom_dweller';

      if (isBottomDweller) {
        fish.preferredDepth = bottomY;
        fish.targetVelocity.y = (bottomY - pos.y) * 0.1;
      } else {
        fish.timer++;
        if (fish.timer > phys.diveInterval) {
          fish.preferredDepth = THREE.MathUtils.randFloat(minY + 0.3, maxY - 0.3);
          fish.timer = 0;
        }
        const depthDiff = fish.preferredDepth - pos.y;
        fish.targetVelocity.y = depthDiff * phys.verticalFreedom;
      }

      if (Math.random() < 0.02) {
        fish.targetVelocity.x += THREE.MathUtils.randFloatSpread(0.015);
        fish.targetVelocity.z += THREE.MathUtils.randFloatSpread(0.015);
      }

      const buffer = 1.3;
      const steer = 0.0035;

      if (pos.x > maxX - buffer) fish.targetVelocity.x -= steer;
      if (pos.x < minX + buffer) fish.targetVelocity.x += steer;

      if (!isBottomDweller) {
        if (pos.y > maxY - buffer) fish.targetVelocity.y -= steer;
        if (pos.y < minY + buffer) fish.targetVelocity.y += steer;
      }

      if (pos.z > maxZ - buffer) fish.targetVelocity.z -= steer;
      if (pos.z < minZ + buffer) fish.targetVelocity.z += steer;

      fish.velocity.lerp(fish.targetVelocity, phys.turnSpeed);
      fish.velocity.clampLength(fish.speed * 0.6, fish.speed * 1.3);

      pos.add(fish.velocity);

      if (pos.x > maxX) { pos.x = maxX; fish.velocity.x *= -0.5; }
      if (pos.x < minX) { pos.x = minX; fish.velocity.x *= -0.5; }

      if (isBottomDweller) {
        pos.y = bottomY;
      } else {
        if (pos.y > maxY) { pos.y = maxY; fish.velocity.y *= -0.5; }
        if (pos.y < minY) { pos.y = minY; fish.velocity.y *= -0.5; }
      }

      if (pos.z > maxZ) { pos.z = maxZ; fish.velocity.z *= -0.5; }
      if (pos.z < minZ) { pos.z = minZ; fish.velocity.z *= -0.5; }

      if (fish.velocity.lengthSq() > 0.00001) {
        const targetPos = pos.clone().add(fish.velocity);
        if (isBottomDweller) {
          targetPos.y = pos.y;
        }
        fish.model.lookAt(targetPos);
      }
    }
  }
}